sources.cmd/invariant/provider_limits_accept_tes:
package main

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strconv"
	"strings"
	"testing"
	"time"

	"github.com/gitdek/invariant/internal/synth"
)

// A CLI stand-in starts the actual MCP command from the backend's config.
// Codex clears the server's environment, apart from its default whitelist
// and explicitly configured env/env_vars; the allowance must be forwarded.
// Every provider attempt starts a fresh server and calls check twice. The
// first attempt then loses its provider before reporting any tool events;
// accounting cannot depend on a completed agent transcript or result.
func TestProviderRetriesShareMCPAllowance(t *testing.T) {
	if providerMCPChild() {
		return
	}
	for _, agent := range []string{"codex", "claude-code"} {
		for _, reports := range []bool{true, false} {
			t.Run(fmt.Sprintf("%s/reports=%v", agent, reports), func(t *testing.T) {
				dir, ws := t.TempDir(), t.TempDir()
				name, body := "issues.json", `{"name":"fixture","summary":"One change.","issues":[{"title":"A change","body":"One change.\n\nKind: plumbing"}]}`
				if !reports {
					// This accepted call currently returns before writing a log.
					name, body = "proposal.json", `{"unsupported":"Fixture: no work to build."}`
				}
				if err := os.WriteFile(filepath.Join(ws, name), []byte(body), 0o600); err != nil {
					t.Fatal(err)
				}
				exe, err := os.Executable()
				if err != nil {
					t.Fatal(err)
				}
				wrap := func(name string, args ...string) string {
					t.Helper()
					quote := func(s string) string { return "'" + strings.ReplaceAll(s, "'", "'\"'\"'") + "'" }
					command := []string{exe, "-test.run=^TestProviderRetriesShareMCPAllowance$", "--", "provider-mcp-fixture"}
					command = append(command, args...)
					for i := range command {
						command[i] = quote(command[i])
					}
					path := filepath.Join(dir, name)
					if err := os.WriteFile(path, []byte("#!/bin/sh\nexec "+strings.Join(command, " ")+" \"$@\"\n"), 0o700); err != nil {
						t.Fatal(err)
					}
					return path
				}
				server := wrap("invariant", "server")
				cli := wrap("agent", "agent", agent, dir)
				var backend synth.Backend
				if agent == "codex" {
					backend = synth.Codex{Binary: cli, Home: t.TempDir(), MaxTurns: 20}
				} else {
					backend = synth.ClaudeCode{Binary: cli, BudgetUSD: 2, MaxTurns: 20}
				}
				if b, ok := backend.(interface {
					WithProviderWait(func(context.Context, time.Duration) error) synth.Backend
				}); ok {
					backend = b.WithProviderWait(func(ctx context.Context, _ time.Duration) error { return ctx.Err() })
				}
				job := synth.Job{Workspace: ws, Prompt: "check the proposal", Tools: []string{"check"}, Timeout: 10 * time.Second,
					GateServer: []string{server, "mcp", "-issues", "-max-runs", "3", "-log", filepath.Join(dir, "checks.jsonl"), ws}}
				ctx, cancel := context.WithTimeout(t.Context(), 30*time.Second)
				defer cancel()
				// A new Run gets a new allowance even with the same workspace,
				// backend and log; only provider attempts share the allowance.
				for run := 0; run < 2; run++ {
					u, err := backend.Run(ctx, job)
					if err != nil || u.Outcome != "success" {
						t.Fatalf("run %d did not recover: usage=%+v error=%v", run+1, u, err)
					}
					admitted, denied := 0, 0
					var allowance string
					for _, attempt := range []int{2*run + 1, 2*run + 2} {
						if agent == "codex" {
							forwarded, err := os.ReadFile(filepath.Join(dir, fmt.Sprintf("allowance.%d", attempt)))
							if err != nil || len(forwarded) == 0 {
								t.Fatalf("attempt %d did not forward its allowance through MCP config: %q, %v", attempt, forwarded, err)
							}
							if allowance != "" && allowance != string(forwarded) {
								t.Fatalf("run %d renewed its MCP allowance on retry: %q became %q", run+1, allowance, forwarded)
							}
							allowance = string(forwarded)
						}
						raw, err := os.ReadFile(filepath.Join(dir, fmt.Sprintf("responses.%d", attempt)))
						if err != nil {
							t.Fatal(err)
						}
						for _, line := range bytes.Split(bytes.TrimSpace(raw), []byte("\n")) {
							var reply struct {
								Result struct {
									Content []struct{ Text string } `json:"content"`
									IsError bool                    `json:"isError"`
								} `json:"result"`
							}
							if err := json.Unmarshal(line, &reply); err != nil || len(reply.Result.Content) != 1 {
								t.Fatalf("bad MCP response %q: %v", line, err)
							}
							text := reply.Result.Content[0].Text
							if reply.Result.IsError && strings.Contains(text, "No checks left") {
								denied++
							} else if !reply.Result.IsError && (strings.Contains(text, "holds together") || strings.Contains(text, "nothing to check")) {
								admitted++
							} else {
								t.Fatalf("unexpected tool result: %s", text)
							}
						}
					}
					if admitted != 3 || denied != 1 {
						t.Fatalf("run %d admitted %d calls and denied %d across two MCP servers; want the original allowance of three", run+1, admitted, denied)
					}
				}
			})
		}
	}
}

// Reexec the test binary as either a provider CLI or invariant mcp. No live
// service, Docker, nested Go build or credentials are needed.
func providerMCPChild() bool {
	var args []string
	for i, arg := range os.Args {
		if arg == "provider-mcp-fixture" {
			args = os.Args[i+1:]
			break
		}
	}
	if len(args) == 0 {
		return false
	}
	fail := func(err error) {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(2)
	}
	if args[0] == "server" {
		if len(args) < 2 || args[1] != "mcp" {
			fail(fmt.Errorf("want mcp command, got %q", args))
		}
		os.Exit(mcpCmd(context.Background(), args[2:]))
	}
	if len(args) < 4 || args[0] != "agent" {
		fail(fmt.Errorf("bad provider fixture args %q", args))
	}
	agent, dir, cliArgs := args[1], args[2], args[3:]
	var command string
	var serverArgs []string
	serverEnv := make(map[string]string)
	var envVars []string
	applyCodexField := func(key, value string) {
		var err error
		switch key {
		case "command":
			err = json.Unmarshal([]byte(value), &command)
		case "args":
			err = json.Unmarshal([]byte(value), &serverArgs)
		case "env_vars":
			err = json.Unmarshal([]byte(value), &envVars)
		case "env":
			var fields map[string]string
			fields, err = providerMCPConfigFields(value)
			if err == nil {
				for name, literal := range fields {
					var v string
					if err = json.Unmarshal([]byte(literal), &v); err != nil {
						break
					}
					serverEnv[name] = v
				}
			}
		default:
			if strings.HasPrefix(key, "env.") {
				var v string
				err = json.Unmarshal([]byte(value), &v)
				serverEnv[strings.TrimPrefix(key, "env.")] = v
			}
		}
		if err != nil {
			fail(fmt.Errorf("cannot read MCP config %s=%s: %w", key, value, err))
		}
	}
	for i, arg := range cliArgs {
		if agent == "claude-code" && arg == "--mcp-config" && i+1 < len(cliArgs) {
			var config struct {
				Servers map[string]struct {
					Command string            `json:"command"`
					Args    []string          `json:"args"`
					Env     map[string]string `json:"env"`
				} `json:"mcpServers"`
			}
			if err := json.Unmarshal([]byte(cliArgs[i+1]), &config); err != nil {
				fail(err)
			}
			command, serverArgs = config.Servers["invariant"].Command, config.Servers["invariant"].Args
			for name, value := range config.Servers["invariant"].Env {
				serverEnv[name] = value
			}
		}
		if agent == "codex" {
			// Accept both the inline server table and separate dotted -c
			// overrides. env sets literal values; env_vars forwards named
			// values from Codex's own environment.
			if strings.HasPrefix(arg, "--config=") {
				arg = strings.TrimPrefix(arg, "--config=")
			} else if i == 0 || (cliArgs[i-1] != "-c" && cliArgs[i-1] != "--config") {
				continue
			}
			key, value, ok := strings.Cut(arg, "=")
			key, value = strings.TrimSpace(key), strings.TrimSpace(value)
			if !ok {
				continue
			}
			if key == "mcp_servers.invariant" {
				fields, err := providerMCPConfigFields(value)
				if err != nil {
					fail(err)
				}
				for field, literal := range fields {
					applyCodexField(field, literal)
				}
			} else if strings.HasPrefix(key, "mcp_servers.invariant.") {
				applyCodexField(strings.TrimPrefix(key, "mcp_servers.invariant."), value)
			}
		}
	}
	if command == "" {
		fail(fmt.Errorf("provider was not given its MCP server: %q", cliArgs))
	}
	count, _ := os.ReadFile(filepath.Join(dir, "attempts"))
	n, _ := strconv.Atoi(strings.TrimSpace(string(count)))
	n++
	if err := os.WriteFile(filepath.Join(dir, "attempts"), []byte(strconv.Itoa(n)), 0o600); err != nil {
		fail(err)
	}
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	cmd := exec.CommandContext(ctx, command, serverArgs...)
	if agent == "codex" {
		// A nil Env would inherit everything and hide a production bug:
		// Codex does not forward INVARIANT_TOOL_ALLOWANCE by default.
		cmd.Env = []string{}
		for _, name := range append([]string{"HOME", "LOGNAME", "PATH", "SHELL", "TMPDIR", "USER"}, envVars...) {
			if value, ok := os.LookupEnv(name); ok {
				cmd.Env = append(cmd.Env, name+"="+value)
			}
		}
	} else {
		cmd.Env = os.Environ()
	}
	for name, value := range serverEnv {
		cmd.Env = append(cmd.Env, name+"="+value)
	}
	if agent == "codex" {
		var allowance string
		for _, entry := range cmd.Env {
			if value, ok := strings.CutPrefix(entry, "INVARIANT_TOOL_ALLOWANCE="); ok {
				allowance = value
			}
		}
		if allowance == "" {
			fail(fmt.Errorf("Codex MCP config did not explicitly forward INVARIANT_TOOL_ALLOWANCE to its filtered server environment"))
		}
		if err := os.WriteFile(filepath.Join(dir, fmt.Sprintf("allowance.%d", n)), []byte(allowance), 0o600); err != nil {
			fail(err)
		}
	}
	cmd.Stdin = strings.NewReader("{\"jsonrpc\":\"2.0\",\"id\":1,\"method\":\"tools/call\",\"params\":{\"name\":\"check\",\"arguments\":{}}}\n" +
		"{\"jsonrpc\":\"2.0\",\"id\":2,\"method\":\"tools/call\",\"params\":{\"name\":\"check\",\"arguments\":{}}}\n")
	var stderr bytes.Buffer
	cmd.Stderr = &stderr
	output, err := cmd.Output()
	if err != nil {
		fail(fmt.Errorf("MCP server: %v: %s", err, stderr.String()))
	}
	if err := os.WriteFile(filepath.Join(dir, fmt.Sprintf("responses.%d", n)), output, 0o600); err != nil {
		fail(err)
	}
	if n%2 == 1 {
		if agent == "codex" {
			fmt.Println(`{"type":"turn.failed","error":{"message":"Selected model is at capacity. Please try a different model."}}`)
		} else {
			fmt.Println(`{"type":"result","subtype":"error_during_execution","is_error":true,"errors":["API Error: 529 overloaded_error"],"total_cost_usd":0.125,"num_turns":1}`)
		}
		os.Exit(1)
	}
	if agent == "codex" {
		fmt.Println(`{"type":"item.completed","item":{"type":"agent_message","text":"Done."}}`)
		fmt.Println(`{"type":"turn.completed"}`)
	} else {
		fmt.Println(`{"type":"result","subtype":"success","result":"Done.","total_cost_usd":0.125,"num_turns":1}`)
	}
	os.Exit(0)
	return true
}

// Read the code-generated TOML subset used by Codex: inline tables containing
// basic strings, arrays and nested tables. Splitting only at top-level commas
// preserves quoted paths and the env table without depending on field order.
func providerMCPConfigFields(value string) (map[string]string, error) {
	value = strings.TrimSpace(value)
	if !strings.HasPrefix(value, "{") || !strings.HasSuffix(value, "}") {
		return nil, fmt.Errorf("want MCP inline table, got %q", value)
	}
	value = value[1 : len(value)-1]
	fields := make(map[string]string)
	start, depth, quoted, escaped := 0, 0, false, false
	for i := 0; i <= len(value); i++ {
		if i == len(value) || (!quoted && depth == 0 && value[i] == ',') {
			field := strings.TrimSpace(value[start:i])
			start = i + 1
			if field == "" {
				continue
			}
			key, literal, ok := strings.Cut(field, "=")
			if !ok {
				return nil, fmt.Errorf("bad MCP config field %q", field)
			}
			key = strings.TrimSpace(key)
			if strings.HasPrefix(key, `"`) {
				if err := json.Unmarshal([]byte(key), &key); err != nil {
					return nil, err
				}
			}
			fields[key] = strings.TrimSpace(literal)
			continue
		}
		if quoted {
			if escaped {
				escaped = false
			} else if value[i] == '\\' {
				escaped = true
			} else if value[i] == '"' {
				quoted = false
			}
			continue
		}
		switch value[i] {
		case '"':
			quoted = true
		case '{', '[':
			depth++
		case '}', ']':
			depth--
		}
	}
	if quoted || depth != 0 {
		return nil, fmt.Errorf("unbalanced MCP config table %q", value)
	}
	return fields, nil
}

sources.internal/factory/provider_failure_accept:
package factory

import (
	"context"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/gitdek/invariant/internal/github"
	"github.com/gitdek/invariant/internal/plumbing"
	"github.com/gitdek/invariant/internal/synth"
)

type providerFailedBuilder struct {
	*fakeBuilder
	err error
}

func (b providerFailedBuilder) Build(ctx context.Context, dir, out string, amend bool) (*synth.Result, error) {
	r, err := b.fakeBuilder.Build(ctx, dir, out, amend)
	if err != nil {
		return r, err
	}
	return r, b.err
}

func TestProviderFailureIsPostedAfterSavingTheBuild(t *testing.T) {
	// A failed gate produces a saved result; publish reconstructs the error
	// from its text, so a post cannot rely on the original error's Go type.
	const last = "Selected model is at capacity. Please try a different model. (last attempt)"
	r := newRig(t)
	r.build.pass = false
	r.f.Builder = providerFailedBuilder{fakeBuilder: r.build,
		err: errors.New("codex provider unavailable after 4 attempts: " + last)}
	ratified(t, r)
	p := r.expect(1, KindFailed, LabelHumanReview)
	for _, want := range []string{"provider unavailable", last, "/invariant retry", "build again"} {
		if !strings.Contains(p.Comment.Body, want) {
			t.Errorf("the failure post lost %q:\n%s", want, p.Comment.Body)
		}
	}
	if len(r.build.built) != 1 {
		t.Errorf("factory repeated the whole build %d times instead of retrying only the agent run", len(r.build.built))
	}
	providerFailureHasNoPR(t, r, p)
}

func TestProviderExhaustionCannotPublishAPassingBuild(t *testing.T) {
	// Use a real backend error, including its classification, without a live
	// service. Both agent and review errors must survive saving and loading
	// the build even when the leftover code passes the final gate.
	backend, calls := providerFactoryCLI(t, "review", true)
	ctx, cancel := context.WithTimeout(t.Context(), 10*time.Second)
	defer cancel()
	_, runErr := backend.Run(ctx, synth.Job{Workspace: t.TempDir(), ReadOnly: true, Timeout: 5 * time.Second})
	if runErr == nil {
		t.Fatal("the exhausted run unexpectedly succeeded")
	}
	if n := providerFactoryAttempts(t, calls); n != 4 {
		t.Errorf("provider attempts = %d; want four before exhaustion", n)
	}
	for _, stage := range []string{"agent", "review"} {
		t.Run(stage, func(t *testing.T) {
			r := newRig(t)
			r.f.Builder = providerFailedBuilder{fakeBuilder: r.build, err: fmt.Errorf("the %s's run failed: %w", stage, runErr)}
			ratified(t, r)
			p := r.expect(1, KindFailed, LabelHumanReview)
			for _, want := range []string{"provider", "unavailable", providerFactoryLastError("review"), "/invariant retry", "build again"} {
				if !strings.Contains(p.Comment.Body, want) {
					t.Errorf("the post lost %q:\n%s", want, p.Comment.Body)
				}
			}
			providerFailureHasNoPR(t, r, p)
		})
	}
}

func providerFailureHasNoPR(t *testing.T, r *rig, p Post) {
	t.Helper()
	if p.Marker.PR != 0 || len(r.gh.prs) != 0 {
		t.Errorf("an unfinished provider run published a pull request: marker PR=%d, pull requests=%v", p.Marker.PR, r.gh.prs)
	}
	if len(r.gh.merged) != 0 {
		t.Errorf("the unfinished run merged unreviewed work: %v", r.gh.merged)
	}
}

// The scripts stand in for the CLI and the sandbox only. The real backend,
// plumbing.Builder, saved build record, and factory retry protocol run here.
// The failed attempts deliberately leave code that passes the checks.
func TestProviderExhaustionRetryRebuildsAndReviewsTheRatifiedPlan(t *testing.T) {
	for _, stage := range []string{"agent", "review"} {
		t.Run(stage, func(t *testing.T) {
			bin := t.TempDir()
			if err := os.WriteFile(filepath.Join(bin, "docker"), []byte(providerFactoryDocker), 0o700); err != nil {
				t.Fatal(err)
			}
			t.Setenv("PATH", bin+string(os.PathListSeparator)+os.Getenv("PATH"))
			r, _ := plumbingRig(t, "page/page.go")
			agent, builds := providerFactoryCLI(t, "agent", stage == "agent")
			reviewer, reviews := providerFactoryCLI(t, "review", stage == "review")
			r.f.Plumbing = plumbing.Builder{Backend: agent, Reviewer: reviewer, Binary: "invariant", TestRuns: 4,
				Timeout: 5 * time.Second, Sandbox: plumbing.Sandbox{Image: "fixture", ModCache: t.TempDir()}}
			r.gh.open(1, "gitdek", "Add a hello page", "Kind: plumbing\n\n/invariant solve")
			r.poll()
			proposal := r.expect(1, KindProposal, LabelProposal)
			hash := proposal.Marker.Proposal.Hash
			r.gh.say(1, "gitdek", "/invariant ratify "+strings.TrimPrefix(hash, "sha256:"))
			providerResumeFailedPost(t, r)
			failed := r.expect(1, KindFailed, LabelHumanReview)
			providerFailureHasNoPR(t, r, failed)
			for _, want := range []string{"provider", "unavailable", providerFactoryLastError(stage), "/invariant retry", "build again"} {
				if !strings.Contains(failed.Comment.Body, want) {
					t.Errorf("the saved %s failure lost %q:\n%s", stage, want, failed.Comment.Body)
				}
			}
			wantBuilds, wantReviews, failedCLI := 4, 0, builds
			if stage == "review" {
				wantBuilds, wantReviews, failedCLI = 1, 4, reviews
			}
			checkCalls := func() {
				t.Helper()
				if b, r := providerFactoryAttempts(t, builds), providerFactoryAttempts(t, reviews); b != wantBuilds || r != wantReviews {
					t.Errorf("agent attempts=%d, review attempts=%d; want %d and %d", b, r, wantBuilds, wantReviews)
				}
			}
			checkCalls()

			// CI success must never substitute for an unfinished review. If a
			// regression publishes a draft, make its CI green before retrying.
			for n := range r.gh.prs {
				r.gh.ci(n, "success")
			}
			before := len(r.gh.posts(1))
			r.poll()
			if len(r.gh.posts(1)) != before {
				t.Error("the failed build posted again without a writer's retry")
			}
			checkCalls()
			if err := os.Remove(filepath.Join(failedCLI, "fail")); err != nil {
				t.Fatal(err)
			}
			r.gh.say(1, "gitdek", "/invariant retry")
			r.poll()
			retrying := r.expect(1, KindRatified, LabelBuilding)
			if retrying.Marker.PR != 0 || retrying.Marker.Hash != hash {
				t.Fatalf("retry must rebuild the same ratified plan without a pull request: %+v", retrying.Marker)
			}
			r.poll()
			pr := r.expect(1, KindPR, LabelPR)
			wantBuilds++
			wantReviews++
			checkCalls()
			if len(r.gh.prs) != 1 || r.gh.prs[pr.Marker.PR].Draft || len(r.gh.merged) != 0 {
				t.Fatalf("a reviewed retry should open its first ready PR and wait for CI: PRs=%v, merged=%v", r.gh.prs, r.gh.merged)
			}
			seen, err := os.ReadFile(filepath.Join(reviews, fmt.Sprintf("reviewed.%d", wantReviews)))
			if err != nil || !strings.Contains(string(seen), fmt.Sprintf("// build attempt %d", wantBuilds)) {
				t.Fatalf("the retry's review must read the rebuilt code: %q, %v", seen, err)
			}
			if !strings.Contains(r.gh.prBody(pr.Marker.PR), "VERDICT: approve") {
				t.Error("the retry's pull request omitted its completed review")
			}
			r.gh.ci(pr.Marker.PR, "success")
			r.poll()
			r.expect(1, KindMerged, LabelMerged)
			if len(r.gh.merged) != 1 || r.gh.merged[0] != pr.Marker.PR {
				t.Errorf("only the rebuilt, reviewed PR may merge: %v", r.gh.merged)
			}
		})
	}
}

var errProviderFailurePostInterrupted = errors.New("the watcher stopped before posting the saved provider failure")

type providerFailurePostInterrupter struct{ GitHub }

func (g providerFailurePostInterrupter) PostComment(ctx context.Context, issue int, body string) (github.Comment, error) {
	if marker, ok := DecodeMarker(body); ok && marker.Kind == KindFailed {
		return github.Comment{}, errProviderFailurePostInterrupted
	}
	return g.GitHub.PostComment(ctx, issue, body)
}

func providerResumeFailedPost(t *testing.T, r *rig) {
	t.Helper()
	hub := r.f.GitHub
	r.f.GitHub = providerFailurePostInterrupter{GitHub: hub}
	if err := r.f.Poll(t.Context()); !errors.Is(err, errProviderFailurePostInterrupted) {
		t.Fatalf("expected the watcher to stop before posting the saved failure, got %v", err)
	}
	// This fresh watcher has no copy of the builder's error. It must recover
	// the saved failure without another agent run or a draft pull request.
	restarted := freshWatcher(r, hub)
	restarted.Plumbing = r.f.Plumbing
	r.f = restarted
	r.poll()
}

func providerFactoryLastError(stage string) string {
	return fmt.Sprintf("Selected model is at capacity. Please try a different model. (%s attempt 4)", stage)
}

func providerFactoryAttempts(t *testing.T, dir string) int {
	t.Helper()
	b, err := os.ReadFile(filepath.Join(dir, "count"))
	if errors.Is(err, os.ErrNotExist) {
		return 0
	}
	var n int
	if err != nil {
		t.Fatal(err)
	}
	if _, err := fmt.Sscan(string(b), &n); err != nil {
		t.Fatal(err)
	}
	return n
}

func providerFactoryCLI(t *testing.T, stage string, failing bool) (synth.Backend, string) {
	t.Helper()
	dir := t.TempDir()
	script := `#!/bin/sh
here=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)
n=0
[ ! -f "$here/count" ] || n=$(cat "$here/count")
n=$((n + 1))
printf '%s\n' "$n" > "$here/count"
if [ STAGE = agent ]; then
  mkdir -p page
  printf '%s\n' 'package page' 'func Hello() string { return "hello" }' "// build attempt $n" > page/page.go
elif [ -f repo/page/page.go ]; then
  cp repo/page/page.go "$here/reviewed.$n"
fi
if [ -f "$here/fail" ]; then
  printf '%s\n' "{\"type\":\"turn.failed\",\"error\":{\"message\":\"Selected model is at capacity. Please try a different model. (STAGE attempt $n)\"}}"
  exit 1
fi
printf '%s\n' '{"type":"item.completed","item":{"type":"agent_message","text":"VERDICT: approve"}}' '{"type":"turn.completed"}'
`
	bin := filepath.Join(dir, "codex")
	if err := os.WriteFile(bin, []byte(strings.ReplaceAll(script, "STAGE", stage)), 0o700); err != nil {
		t.Fatal(err)
	}
	if failing {
		if err := os.WriteFile(filepath.Join(dir, "fail"), nil, 0o600); err != nil {
			t.Fatal(err)
		}
	}
	var backend synth.Backend = synth.Codex{Binary: bin, Home: t.TempDir(), MaxTurns: 20}
	// The optional interface keeps the test compilable on the base branch,
	// where missing retry behavior must fail the behavioral assertions.
	if configurable, ok := backend.(interface {
		WithProviderWait(func(context.Context, time.Duration) error) synth.Backend
	}); ok {
		backend = configurable.WithProviderWait(func(ctx context.Context, _ time.Duration) error { return ctx.Err() })
	}
	return backend, dir
}

const providerFactoryDocker = `#!/bin/sh
[ "$1" = run ] || exit 0
src=
for a in "$@"; do
  case "$a" in
    *:/src) src=${a%:/src} ;;
  esac
done
echo '@@invariant vet=0'
echo '@@invariant test=0'
if grep -q 'func Hello' "$src/page/page.go" 2>/dev/null; then
  echo '--- PASS: TestPageSaysHello (0.00s)'
  echo '@@invariant accept=0'
else
  echo '--- FAIL: TestPageSaysHello (0.00s)'
  echo '@@invariant accept=1'
fi
`

