package plumbing

import (
	"context"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/gitdek/invariant/internal/synth"
)

type providerReviewProbe struct{ calls int }

func (*providerReviewProbe) Name() string { return "fixture" }
func (p *providerReviewProbe) Run(context.Context, synth.Job) (synth.Usage, error) {
	p.calls++
	return synth.Usage{Outcome: "success", Summary: "VERDICT: approve"}, nil
}

func TestPlumbingBuildFailsWhenItsProviderNeverFinishes(t *testing.T) {
	// The existing checkout fixture supplies a fake sandbox whose checks pass
	// for Hello. This isolates the run failure from an unrelated test failure.
	root := loopyCheckout(t)
	bin := filepath.Join(t.TempDir(), "codex")
	script := `#!/bin/sh
mkdir -p page
printf '%s\n' 'package page' 'func Hello() string { return "hello" }' > page/page.go
printf '%s\n' '{"type":"turn.failed","error":{"message":"Selected model is at capacity. Please try a different model."}}'
exit 1
`
	if err := os.WriteFile(bin, []byte(script), 0o700); err != nil {
		t.Fatal(err)
	}
	reviewer := &providerReviewProbe{}
	b := Builder{Backend: synth.Codex{Binary: bin, Home: t.TempDir()}, Reviewer: reviewer,
		Binary: "invariant", TestRuns: 4, Timeout: 300 * time.Millisecond, FallbackEffort: "xhigh",
		Sandbox: Sandbox{Image: "golang", ModCache: t.TempDir()}}
	ctx, cancel := context.WithTimeout(t.Context(), 10*time.Second)
	defer cancel()
	r, err := b.Build(ctx, root, 7, filepath.Join(t.TempDir(), "build"))
	if err != nil || r == nil {
		t.Fatalf("build result=%+v, error=%v; want a recorded failed build", r, err)
	}
	if r.Passed || r.Approved || reviewer.calls != 0 || r.Fallback != nil {
		t.Errorf("an exhausted provider was treated as a finished build or thinking-loop fallback: passed=%v approved=%v reviews=%d fallback=%+v", r.Passed, r.Approved, reviewer.calls, r.Fallback)
	}
	for _, want := range []string{"provider", "unavailable", "Selected model is at capacity."} {
		if !strings.Contains(r.Summary, want) {
			t.Errorf("build summary lost %q: %s", want, r.Summary)
		}
	}
}

type providerHelloBuilder struct{}

func (providerHelloBuilder) Name() string { return "fixture" }
func (providerHelloBuilder) Run(_ context.Context, job synth.Job) (synth.Usage, error) {
	if err := os.MkdirAll(filepath.Join(job.Workspace, "page"), 0o755); err != nil {
		return synth.Usage{}, err
	}
	err := os.WriteFile(filepath.Join(job.Workspace, "page", "page.go"), []byte("package page\nfunc Hello() string { return \"hello\" }\n"), 0o644)
	return synth.Usage{Outcome: "success"}, err
}

func TestPlumbingReviewsRetryAndReportProviderExhaustion(t *testing.T) {
	for _, succeeds := range []bool{true, false} {
		t.Run(fmt.Sprintf("eventually succeeds=%v", succeeds), func(t *testing.T) {
			root := loopyCheckout(t)
			dir := t.TempDir()
			bin := filepath.Join(dir, "codex")
			script := `#!/bin/sh
here=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)
if [ -f "$here/attempted" ] && [ SUCCEEDS = true ]; then
  printf '%s\n' '{"type":"item.completed","item":{"type":"agent_message","text":"VERDICT: approve"}}' '{"type":"turn.completed"}'
  exit 0
fi
touch "$here/attempted"
printf '%s\n' '{"type":"turn.failed","error":{"message":"Selected model is at capacity. Please try a different model."}}'
exit 1
`
			script = strings.ReplaceAll(script, "SUCCEEDS", fmt.Sprint(succeeds))
			if err := os.WriteFile(bin, []byte(script), 0o700); err != nil {
				t.Fatal(err)
			}
			timeout := 30 * time.Second
			if !succeeds {
				timeout = 300 * time.Millisecond
			}
			var reviewer synth.Backend = synth.Codex{Binary: bin, Home: t.TempDir()}
			// Keep the one-minute production wait short here. The type
			// assertion lets the base branch run and fail behaviorally too.
			if c, ok := reviewer.(interface {
				WithProviderWait(func(context.Context, time.Duration) error) synth.Backend
			}); ok {
				reviewer = c.WithProviderWait(func(ctx context.Context, delay time.Duration) error {
					timer := time.NewTimer(delay / 12)
					defer timer.Stop()
					select {
					case <-ctx.Done():
						return ctx.Err()
					case <-timer.C:
						return nil
					}
				})
			}
			b := Builder{Backend: providerHelloBuilder{}, Reviewer: reviewer,
				Binary: "invariant", TestRuns: 4, Timeout: timeout, Sandbox: Sandbox{Image: "golang", ModCache: t.TempDir()}}
			ctx, cancel := context.WithTimeout(t.Context(), 40*time.Second)
			defer cancel()
			r, err := b.Build(ctx, root, 7, filepath.Join(t.TempDir(), "build"))
			if err != nil || r == nil || !r.Passed {
				t.Fatalf("fixture build failed: %+v, %v", r, err)
			}
			if r.Approved != succeeds {
				t.Errorf("review approved=%v, want %v: %s", r.Approved, succeeds, r.Review)
			}
			if !succeeds {
				for _, want := range []string{"provider", "unavailable", "Selected model is at capacity."} {
					if !strings.Contains(r.Review, want) {
						t.Errorf("review failure lost %q: %s", want, r.Review)
					}
				}
			}
		})
	}
}

sources.internal/synth/provider_limits_accept_te:
package synth

import (
	"context"
	"errors"
	"fmt"
	"math"
	"os"
	"path/filepath"
	"reflect"
	"sort"
	"strconv"
	"strings"
	"testing"
	"time"
)

// Each attempt reports real work before its terminal provider error. This
// makes replacing an earlier attempt's usage observable, even when the last
// attempt succeeds, fails normally, or exhausts the provider retry policy.
func providerClaudeUsageAttempt(outcome, summary string, cost float64, turns int, calls map[string]int) providerAttempt {
	init := map[string]any{"type": "system", "subtype": "init", "model": "fixture-model"}
	for name := range calls {
		if strings.HasPrefix(name, "mcp__invariant__") {
			init["mcp_servers"] = []map[string]string{{"name": "invariant", "status": "connected"}}
		}
	}
	out := providerJSON(init)
	var names []string
	for name := range calls {
		names = append(names, name)
	}
	sort.Strings(names)
	var content []map[string]any
	for _, name := range names {
		for i := 0; i < calls[name]; i++ {
			content = append(content, map[string]any{"type": "tool_use", "name": name,
				"id": fmt.Sprintf("%s-%d", name, i), "input": map[string]any{}})
		}
	}
	if len(content) > 0 {
		out += providerJSON(map[string]any{"type": "assistant", "message": map[string]any{
			"id": "attempt-work", "role": "assistant", "model": "fixture-model", "content": content,
			"usage": map[string]int{"input_tokens": 100, "output_tokens": 30,
				"cache_creation_input_tokens": 1000, "cache_read_input_tokens": 2000},
		}})
	}
	result := map[string]any{
		"type": "result", "subtype": outcome, "result": summary,
		"total_cost_usd": cost, "num_turns": turns, "is_error": outcome != "success",
	}
	exit := 0
	if outcome != "success" {
		result["errors"], exit = []string{summary}, 1
	}
	return providerAttempt{out: out + providerJSON(result), exit: exit}
}

func providerCodexUsageAttempt(success bool, summary string, tools ...string) providerAttempt {
	out := "{\"type\":\"turn.started\"}\n"
	for _, tool := range tools {
		item := map[string]any{"type": tool, "status": "completed"}
		if tool == "mcp_tool_call" {
			item["server"], item["tool"] = "invariant", "gate"
		}
		out += providerJSON(map[string]any{"type": "item.completed", "item": item})
	}
	if !success {
		out += providerJSON(map[string]any{"type": "turn.failed", "error": map[string]string{"message": summary}})
		return providerAttempt{out: out, exit: 1}
	}
	out += providerJSON(map[string]any{"type": "item.completed", "item": map[string]string{"type": "agent_message", "text": summary}})
	out += "{\"type\":\"turn.completed\",\"usage\":{\"input_tokens\":10,\"output_tokens\":2}}\n"
	return providerAttempt{out: out}
}

func providerNoWait(ctx context.Context, _ time.Duration) error { return ctx.Err() }

func providerFlag(t *testing.T, dir string, attempt int, flag string) string {
	t.Helper()
	b, err := os.ReadFile(filepath.Join(dir, fmt.Sprintf("args.%d", attempt)))
	if err != nil {
		t.Fatal(err)
	}
	args := strings.Split(string(b), "\n")
	for i, arg := range args {
		if arg == flag && i+1 < len(args) {
			return args[i+1]
		}
	}
	t.Fatalf("attempt %d omitted %s: %q", attempt, flag, args)
	return ""
}

func TestProviderRetriesSumUsageAndKeepTheLastOutcome(t *testing.T) {
	for _, agent := range []string{"codex", "claude-code"} {
		for _, ending := range []string{"success", "ordinary failure", "provider exhaustion"} {
			t.Run(agent+"/"+ending, func(t *testing.T) {
				last := "Last attempt completed the job."
				wantOutcome := "success"
				n := 3
				if ending != "success" {
					last, wantOutcome = "Invalid API key on the last attempt", "failed"
					if ending == "provider exhaustion" {
						last, n = providerCapacity+" (last attempt)", 4
					}
					if agent == "claude-code" {
						wantOutcome = "error_during_execution"
						if ending == "provider exhaustion" {
							last = "API Error: 529 overloaded_error (last attempt)"
						}
					}
				}
				var attempts []providerAttempt
				want := Usage{Outcome: wantOutcome, Summary: last, ToolCalls: map[string]int{}}
				for i := 0; i < n; i++ {
					final := i == n-1
					if agent == "claude-code" {
						outcome, summary := "error_during_execution", "API Error: 529 overloaded_error"
						if final {
							outcome, summary = wantOutcome, last
						}
						calls := map[string]int{"Read": i + 1, "mcp__invariant__gate": 1}
						cost, turns := .0625*float64(i+1), i+2
						attempts = append(attempts, providerClaudeUsageAttempt(outcome, summary, cost, turns, calls))
						want.CostUSD += cost
						want.Turns += turns
						for tool, count := range calls {
							want.ToolCalls[tool] += count
						}
					} else {
						summary := providerCapacity
						if final {
							summary = last
						}
						attempts = append(attempts, providerCodexUsageAttempt(final && ending == "success", summary,
							"command_execution", "file_change", "mcp_tool_call"))
						want.Turns += 3
						if final && ending == "success" {
							want.Turns++ // the closing agent message is also a Codex step
						}
						for _, tool := range []string{"shell", "edit", "mcp__invariant__gate"} {
							want.ToolCalls[tool]++
						}
					}
				}
				b, dir := providerBackend(t, agent, attempts...)
				b = providerWithWait(b, providerNoWait)
				u, err := b.Run(providerContext(t), Job{Workspace: t.TempDir(), GateServer: []string{"invariant", "mcp"}, Timeout: 5 * time.Second})
				if ending == "success" && err != nil || ending != "success" && err == nil {
					t.Errorf("last outcome %q returned error %v", ending, err)
				}
				if ending == "provider exhaustion" {
					providerUnavailable(t, err, last)
				}
				if got := providerCount(t, dir); got != n {
					t.Errorf("attempts=%d; want %d", got, n)
				}
				if u.Turns != want.Turns || math.Abs(u.CostUSD-want.CostUSD) > 1e-9 || !reflect.DeepEqual(u.ToolCalls, want.ToolCalls) {
					t.Errorf("aggregate usage=%+v; want turns=%d cost=%g tools=%v", u, want.Turns, want.CostUSD, want.ToolCalls)
				}
				if u.Outcome != want.Outcome || u.Summary != last {
					t.Errorf("final outcome=%q summary=%q; want %q and %q", u.Outcome, u.Summary, want.Outcome, last)
				}
			})
		}
	}
}

func TestClaudeRetriesReceiveOnlyTheRemainingBudgetAndTurns(t *testing.T) {
	first := providerClaudeUsageAttempt("error_during_execution", "API Error: 529 overloaded_error", .125, 2, map[string]int{"Read": 1})
	second := providerClaudeUsageAttempt("error_during_execution", "API Error: 429 rate_limit_error", .25, 1, map[string]int{"Read": 1})
	third := providerClaudeUsageAttempt("success", "Done.", .25, 2, map[string]int{"Read": 1})
	bin, dir := providerCLI(t, first, second, third)
	b := providerWithWait(ClaudeCode{Binary: bin, Model: "fixture-model", BudgetUSD: 1, MaxTurns: 7}, providerNoWait)
	u, err := b.Run(providerContext(t), Job{Workspace: t.TempDir(), ReadOnly: true, Timeout: 5 * time.Second})
	if err != nil || u.Outcome != "success" || providerCount(t, dir) != 3 {
		t.Fatalf("retry sequence: usage=%+v, error=%v, attempts=%d", u, err, providerCount(t, dir))
	}
	for i, wantBudget := range []float64{1, .875, .625} {
		budget, err := strconv.ParseFloat(providerFlag(t, dir, i+1, "--max-budget-usd"), 64)
		if err != nil || math.Abs(budget-wantBudget) > 1e-9 {
			t.Errorf("attempt %d budget=%g (%v); want exactly %g, without rounding the remaining allowance upward", i+1, budget, err, wantBudget)
		}
		turns, err := strconv.Atoi(providerFlag(t, dir, i+1, "--max-turns"))
		wantTurns := []int{7, 5, 4}[i]
		if err != nil || turns != wantTurns {
			t.Errorf("attempt %d turns=%d (%v); want remaining %d", i+1, turns, err, wantTurns)
		}
	}
	if u.Turns != 5 || math.Abs(u.CostUSD-.625) > 1e-9 {
		t.Errorf("usage=%+v; want five turns and $0.625 for the whole run", u)
	}
}

func TestClaudeProviderRetriesCannotRenewAnExhaustedLimit(t *testing.T) {
	for _, limit := range []string{"budget", "turns"} {
		t.Run(limit, func(t *testing.T) {
			cost, turns := .25, 2
			if limit == "budget" {
				cost = 1
			} else {
				turns = 7
			}
			failure := providerClaudeUsageAttempt("error_during_execution", "API Error: 529 overloaded_error", cost, turns, map[string]int{"Read": 1})
			bin, dir := providerCLI(t, failure, providerSuccess("claude-code"))
			waits := 0
			b := providerWithWait(ClaudeCode{Binary: bin, Model: "fixture-model", BudgetUSD: 1, MaxTurns: 7}, func(ctx context.Context, _ time.Duration) error {
				waits++
				return ctx.Err()
			})
			u, err := b.Run(providerContext(t), Job{Workspace: t.TempDir(), ReadOnly: true, Timeout: 5 * time.Second})
			if err == nil || !strings.Contains(strings.ToLower(err.Error()), strings.TrimSuffix(limit, "s")) {
				t.Errorf("exhausted %s returned %v; want a diagnostic identifying the exhausted limit", limit, err)
			}
			if count := providerCount(t, dir); count != 1 || waits != 0 {
				t.Errorf("exhausted %s launched %d attempts and waited %d times; want one attempt and no wait", limit, count, waits)
			}
			if u.Outcome != "error_during_execution" || u.Turns != turns || math.Abs(u.CostUSD-cost) > 1e-9 {
				t.Errorf("limit exhaustion lost the last attempt's outcome or usage: %+v", u)
			}
		})
	}
}

func TestClaudeProviderRetryStopsAtTheRemainingLimit(t *testing.T) {
	// The stand-in CLI needs two more turns and $0.50 on attempt two. It
	// honors the actual limits supplied by the backend, as Claude Code does.
	// A renewed allowance lets it succeed, which is the bug under test.
	for _, limit := range []string{"budget", "turns"} {
		t.Run(limit, func(t *testing.T) {
			cost, turns, flag := .75, 1, "--max-budget-usd"
			wantOutcome, wantCost, wantTurns := "error_max_budget_usd", 1.0, 2
			before := `budget=$(awk '$0 == "--max-budget-usd" {getline; print; exit}' "$here/args.$n")
awk -v remaining="$budget" 'BEGIN {
  if (remaining < 0.5) {
    printf "{\"type\":\"result\",\"subtype\":\"error_max_budget_usd\",\"is_error\":true,\"result\":\"Budget exhausted\",\"num_turns\":1,\"total_cost_usd\":%.9f}\n", remaining
  } else {
    print "{\"type\":\"result\",\"subtype\":\"success\",\"result\":\"Done.\",\"num_turns\":1,\"total_cost_usd\":0.5}"
  }
}' > "$here/out.$i"
`
			wantRemaining := .25
			if limit == "turns" {
				cost, turns, flag = .125, 3, "--max-turns"
				wantOutcome, wantCost, wantTurns, wantRemaining = "error_max_turns", .25, 4, 1
				before = `turns=$(awk '$0 == "--max-turns" {getline; print; exit}' "$here/args.$n")
awk -v remaining="$turns" 'BEGIN {
  if (remaining < 2) {
    printf "{\"type\":\"result\",\"subtype\":\"error_max_turns\",\"is_error\":true,\"result\":\"Turn limit reached\",\"num_turns\":%d,\"total_cost_usd\":0.125}\n", remaining
  } else {
    print "{\"type\":\"result\",\"subtype\":\"success\",\"result\":\"Done.\",\"num_turns\":2,\"total_cost_usd\":0.125}"
  }
}' > "$here/out.$i"
`
			}
			first := providerClaudeUsageAttempt("error_during_execution", "API Error: 529 overloaded_error", cost, turns, nil)
			second := providerAttempt{before: before}
			bin, dir := providerCLI(t, first, second, providerSuccess("claude-code"))
			b := providerWithWait(ClaudeCode{Binary: bin, Model: "fixture-model", BudgetUSD: 1, MaxTurns: 4}, providerNoWait)
			u, err := b.Run(providerContext(t), Job{Workspace: t.TempDir(), ReadOnly: true, Timeout: 5 * time.Second})
			if err == nil || u.Outcome != wantOutcome || providerCount(t, dir) != 2 {
				t.Fatalf("retry renewed %s: usage=%+v error=%v attempts=%d", limit, u, err, providerCount(t, dir))
			}
			remaining, parseErr := strconv.ParseFloat(providerFlag(t, dir, 2, flag), 64)
			if parseErr != nil || math.Abs(remaining-wantRemaining) > 1e-9 {
				t.Errorf("second attempt %s=%g (%v); want %g", flag, remaining, parseErr, wantRemaining)
			}
			if u.Turns != wantTurns || math.Abs(u.CostUSD-wantCost) > 1e-9 {
				t.Errorf("usage=%+v; want %d turns, cost %g at the shared limit", u, wantTurns, wantCost)
			}
		})
	}
}

// Claude Code reports token usage on assistant messages, but dollars only
// on the closing result. These are paid replies followed by a provider
// disconnect, with no result from which to learn the final cost. The model
// deliberately has no known price: a guessed conversion from tokens must
// not authorize another paid attempt.
func providerClaudeIncompletePaidAttempt() providerAttempt {
	return providerAttempt{out: `{"type":"system","subtype":"init","model":"fixture-model"}
{"type":"assistant","message":{"id":"paid-reply-1","type":"message","role":"assistant","model":"fixture-model","content":[{"type":"tool_use","id":"read-before-disconnect","name":"Read","input":{"file_path":"source.go"}}],"stop_reason":"tool_use","usage":{"input_tokens":120,"cache_creation_input_tokens":1000,"cache_read_input_tokens":2000,"output_tokens":40}}}
{"type":"user","message":{"role":"user","content":[{"type":"tool_result","tool_use_id":"read-before-disconnect","content":"package example"}]}}
{"type":"assistant","message":{"id":"paid-reply-2","type":"message","role":"assistant","model":"fixture-model","content":[{"type":"text","text":"I found the problem and am checking the fix."}],"stop_reason":"end_turn","usage":{"input_tokens":140,"cache_creation_input_tokens":0,"cache_read_input_tokens":3000,"output_tokens":60}}}
`, stderr: "API request failed: connection reset by peer\n", exit: 1}
}

func TestClaudeIncompletePaidAttemptCannotRenewTheDollarBudget(t *testing.T) {
	for _, afterRetry := range []bool{false, true} {
		t.Run(fmt.Sprintf("after a reported paid failure=%v", afterRetry), func(t *testing.T) {
			var attempts []providerAttempt
			wantTurns, wantReads := 2, 1
			if afterRetry {
				attempts = append(attempts, providerClaudeUsageAttempt("error_during_execution", "API Error: 529 overloaded_error", .125, 3, map[string]int{"Read": 2}))
				wantTurns, wantReads = 5, 3
			}
			attempts = append(attempts, providerClaudeIncompletePaidAttempt(), providerSuccess("claude-code"))
			bin, dir := providerCLI(t, attempts...)
			waits := 0
			b := providerWithWait(ClaudeCode{Binary: bin, Model: "fixture-model", BudgetUSD: 1, MaxTurns: 9}, func(ctx context.Context, _ time.Duration) error {
				waits++
				return ctx.Err()
			})
			u, err := b.Run(providerContext(t), Job{Workspace: t.TempDir(), ReadOnly: true, Timeout: 5 * time.Second})
			if err == nil {
				t.Fatal("paid work with no closing cost result renewed the dollar budget and succeeded")
			}
			diagnostic := strings.ToLower(err.Error())
			if !strings.Contains(diagnostic, "connection reset by peer") || !strings.Contains(diagnostic, "budget") {
				t.Errorf("failure=%v; want the provider disconnect and the reason its remaining budget cannot be reused", err)
			}
			if !strings.Contains(diagnostic, "incomplete") && !strings.Contains(diagnostic, "unknown") && !strings.Contains(diagnostic, "uncertain") && !strings.Contains(diagnostic, "conservative") {
				t.Errorf("failure=%v; want explicit notice that final cost is unavailable and accounting is conservative", err)
			}
			wantAttempts := len(attempts) - 1
			if count := providerCount(t, dir); count != wantAttempts || waits != wantAttempts-1 {
				t.Errorf("attempts=%d waits=%d; want %d attempts and %d waits, with none after the incomplete paid attempt", count, waits, wantAttempts, wantAttempts-1)
			}
			// Reserve the whole remaining allowance when the final cost is
			// unknown, keeping this conservative estimate visible in Usage.
			// Earlier reported costs count once; their budget is not reserved
			// again. This is an estimate for the limit, never a known charge.
			if math.Abs(u.CostUSD-1) > 1e-9 || u.Turns != wantTurns || u.ToolCalls["Read"] != wantReads || u.Outcome == "success" {
				t.Errorf("incomplete usage=%+v; want the $1 conservative run estimate, %d observed turns, %d reads and no success", u, wantTurns, wantReads)
			}
			if afterRetry {
				remaining, parseErr := strconv.ParseFloat(providerFlag(t, dir, 2, "--max-budget-usd"), 64)
				if parseErr != nil || math.Abs(remaining-.875) > 1e-9 {
					t.Errorf("incomplete attempt budget=%g (%v); want the remaining $0.875", remaining, parseErr)
				}
			}
		})
	}
}

func TestClaudeClosingResultsReconcilePaidAssistantUsage(t *testing.T) {
	// The same paid events are followed by a real result here. Its cost and
	// turns are authoritative; observing tokens must neither reserve the
	// remaining budget nor double-count usage already included in that result.
	first := providerClaudeIncompletePaidAttempt()
	first.out += providerJSON(map[string]any{"type": "result", "subtype": "error_during_execution", "is_error": true,
		"result": "API Error: 529 overloaded_error", "errors": []string{"API Error: 529 overloaded_error"},
		"total_cost_usd": .125, "num_turns": 2})
	first.stderr = ""
	second := providerClaudeIncompletePaidAttempt()
	second.out += providerJSON(map[string]any{"type": "result", "subtype": "success", "is_error": false,
		"result": "The provider recovered.", "total_cost_usd": .25, "num_turns": 2})
	second.stderr, second.exit = "", 0
	bin, dir := providerCLI(t, first, second)
	b := providerWithWait(ClaudeCode{Binary: bin, Model: "fixture-model", BudgetUSD: 1, MaxTurns: 9}, providerNoWait)
	u, err := b.Run(providerContext(t), Job{Workspace: t.TempDir(), ReadOnly: true, Timeout: 5 * time.Second})
	if err != nil || providerCount(t, dir) != 2 || u.Outcome != "success" || u.Summary != "The provider recovered." {
		t.Fatalf("reported costs should permit recovery: usage=%+v error=%v attempts=%d", u, err, providerCount(t, dir))
	}
	if math.Abs(u.CostUSD-.375) > 1e-9 || u.Turns != 4 || u.ToolCalls["Read"] != 2 {
		t.Errorf("reported results must replace each attempt's provisional accounting: %+v; want $0.375, four turns and two reads", u)
	}
	remaining, parseErr := strconv.ParseFloat(providerFlag(t, dir, 2, "--max-budget-usd"), 64)
	if parseErr != nil || math.Abs(remaining-.875) > 1e-9 {
		t.Errorf("second attempt budget=%g (%v); want $0.875 from the first result", remaining, parseErr)
	}
}

func TestCodexProviderRetriesShareTheStepLimit(t *testing.T) {
	// The first attempt consumes two of three steps; the next consumes the
	// last. Both stop at capacity, but there is no allowance for a third CLI.
	first := providerCodexUsageAttempt(false, providerCapacity, "command_execution", "file_change")
	second := providerCodexUsageAttempt(false, providerCapacity, "command_execution")
	bin, dir := providerCLI(t, first, second, providerSuccess("codex"))
	waits := 0
	b := providerWithWait(Codex{Binary: bin, Home: t.TempDir(), MaxTurns: 3}, func(ctx context.Context, _ time.Duration) error {
		waits++
		return ctx.Err()
	})
	u, err := b.Run(providerContext(t), Job{Workspace: t.TempDir(), ReadOnly: true, Timeout: 5 * time.Second})
	if !errors.Is(err, ErrTooManyTurns) {
		t.Errorf("spent the run's steps: error=%v; want the existing step-limit error", err)
	}
	if attempts := providerCount(t, dir); attempts != 2 || waits != 1 {
		t.Errorf("attempts=%d waits=%d; want two attempts and one wait before exhausting the shared step limit", attempts, waits)
	}
	if u.Turns != 3 || u.ToolCalls["shell"] != 2 || u.ToolCalls["edit"] != 1 || u.Outcome == "success" {
		t.Errorf("step-limit usage=%+v; want the work from both attempts and a failed outcome", u)
	}
}

sources.internal/synth/provider_retry_accept_tes:
package synth

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"reflect"
	"strconv"
	"strings"
	"sync"
	"syscall"
	"testing"
	"time"
)

// These are CLI stand-ins, not live providers. The public Backend.Run and
// RunAgent APIs exercise the actual parsing, process lifetime and turn locks.
// The policy under test is four attempts, with one-, two- and four-minute
// waits. Tests shorten the actual waits through WithProviderWait, leaving
// the schedule requested by the backend unchanged.
type providerAttempt struct {
	out, stderr, before string
	exit                int
}

func providerCLI(t *testing.T, attempts ...providerAttempt) (string, string) {
	t.Helper()
	dir := t.TempDir()
	script := `#!/bin/sh
here=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)
n=0
[ ! -f "$here/count" ] || n=$(cat "$here/count")
n=$((n + 1))
printf '%s\n' "$n" > "$here/count"
printf '%s\n' "$@" > "$here/args.$n"
pwd > "$here/workspace.$n"
i=$n
[ -f "$here/out.$i" ] || i=LAST
. "$here/before.$i"
cat "$here/out.$i"
cat "$here/stderr.$i" >&2
exit "$(cat "$here/exit.$i")"
`
	script = strings.ReplaceAll(script, "i=LAST", fmt.Sprintf("i=%d", len(attempts)))
	write := func(name, content string) {
		t.Helper()
		if err := os.WriteFile(filepath.Join(dir, name), []byte(content), 0o700); err != nil {
			t.Fatal(err)
		}
	}
	write("agent", script)
	for i, a := range attempts {
		n := strconv.Itoa(i + 1)
		write("out."+n, a.out)
		write("stderr."+n, a.stderr)
		write("before."+n, a.before)
		write("exit."+n, strconv.Itoa(a.exit))
	}
	return filepath.Join(dir, "agent"), dir
}

func providerJSON(v any) string {
	b, _ := json.Marshal(v)
	return string(b) + "\n"
}

const providerCapacity = "Selected model is at capacity. Please try a different model."

func providerCodexFailure(message string) providerAttempt {
	return providerAttempt{out: providerJSON(map[string]any{
		"type": "turn.failed", "error": map[string]string{"message": message},
	}), exit: 1}
}

func providerClaudeFailure(message string) providerAttempt {
	return providerAttempt{out: providerJSON(map[string]any{
		"type": "result", "subtype": "error_during_execution", "is_error": true,
		"errors": []string{message}, "num_turns": 1, "total_cost_usd": .125,
	}), exit: 1}
}

func providerSuccess(agent string) providerAttempt {
	if agent == "codex" {
		return providerAttempt{out: providerJSON(map[string]any{
			"type": "item.completed", "item": map[string]string{"type": "agent_message", "text": "Done."},
		}) + "{\"type\":\"turn.completed\",\"usage\":{\"input_tokens\":10,\"output_tokens\":2}}\n"}
	}
	return providerAttempt{out: "{\"type\":\"result\",\"subtype\":\"success\",\"result\":\"Done.\",\"num_turns\":1}\n"}
}

func providerBackend(t *testing.T, agent string, attempts ...providerAttempt) (Backend, string) {
	t.Helper()
	bin, dir := providerCLI(t, attempts...)
	var b Backend
	if agent == "codex" {
		b = Codex{Binary: bin, Home: t.TempDir(), Model: "fixture-model", Effort: "high", MaxTurns: 20}
	} else {
		b = ClaudeCode{Binary: bin, Model: "fixture-model", Effort: "high", MaxTurns: 20, BudgetUSD: 1}
	}
	return providerWithWait(b, providerScaledWait(12)), dir
}

// WithProviderWait returns the same concrete backend value with a waiting
// function for this instance only; nil restores its cancellable timer.
// The assertion keeps these tests runnable on the base branch, where the
// method is absent and the real Run behavior must still fail each test.
func providerWithWait(b Backend, wait func(context.Context, time.Duration) error) Backend {
	if c, ok := b.(interface {
		WithProviderWait(func(context.Context, time.Duration) error) Backend
	}); ok {
		return c.WithProviderWait(wait)
	}
	return b
}

func providerScaledWait(divisor int64) func(context.Context, time.Duration) error {
	return func(ctx context.Context, delay time.Duration) error {
		timer := time.NewTimer(delay / time.Duration(divisor))
		defer timer.Stop()
		select {
		case <-ctx.Done():
			return ctx.Err()
		case <-timer.C:
			return nil
		}
	}
}

func providerCount(t *testing.T, dir string) int {
	t.Helper()
	b, err := os.ReadFile(filepath.Join(dir, "count"))
	if err != nil {
		t.Fatal(err)
	}
	n, err := strconv.Atoi(strings.TrimSpace(string(b)))
	if err != nil {
		t.Fatal(err)
	}
	return n
}

func providerContext(t *testing.T) context.Context {
	t.Helper()
	ctx, cancel := context.WithTimeout(t.Context(), 40*time.Second)
	t.Cleanup(cancel)
	return ctx
}

func providerUnavailable(t *testing.T, err error, last string) {
	t.Helper()
	if err == nil || !strings.Contains(strings.ToLower(err.Error()), "provider") ||
		!strings.Contains(strings.ToLower(err.Error()), "unavailable") || !strings.Contains(err.Error(), last) {
		t.Errorf("failure = %v; want provider unavailable and the last provider error %q", err, last)
	}
}

func TestCodexRetriesCapacityWithTheSameJob(t *testing.T) {
	t.Parallel()
	first := providerCodexFailure(providerCapacity)
	first.before = "printf 'work already done' > partial.txt\n"
	second := providerSuccess("codex")
	second.before = "[ \"$(cat partial.txt)\" = 'work already done' ] || exit 42\n"
	b, dir := providerBackend(t, "codex", first, second)
	var transcript bytes.Buffer
	job := Job{Workspace: t.TempDir(), Prompt: "finish this build", GateServer: []string{"invariant", "mcp"},
		Tools: []string{"test"}, Effort: "high", Transcript: &transcript}
	start := time.Now()
	u, fallback, err := RunAgent(providerContext(t), b, job, 30*time.Second, "xhigh")
	if err != nil || u.Outcome != "success" || fallback != nil {
		t.Fatalf("capacity then success: usage=%+v, fallback=%+v, error=%v", u, fallback, err)
	}
	if n := providerCount(t, dir); n != 2 {
		t.Fatalf("ran %d attempts; want two", n)
	}
	if time.Since(start) < 5*time.Second {
		t.Error("the retry did not observe the configured five-second wait")
	}
	for _, prefix := range []string{"args.", "workspace."} {
		a, err1 := os.ReadFile(filepath.Join(dir, prefix+"1"))
		b, err2 := os.ReadFile(filepath.Join(dir, prefix+"2"))
		// The command's per-attempt temporary directory is allowed to change.
		if prefix == "args." {
			strip := func(s []byte) string {
				var kept []string
				for _, line := range strings.Split(string(s), "\n") {
					if !strings.HasPrefix(line, "shell_environment_policy.set=") {
						kept = append(kept, line)
					}
				}
				return strings.Join(kept, "\n")
			}
			if err1 != nil || err2 != nil || strip(a) != strip(b) {
				t.Errorf("retry changed the job: %q / %q (%v, %v)", a, b, err1, err2)
			}
		} else if err1 != nil || err2 != nil || !bytes.Equal(a, b) {
			t.Errorf("retry changed workspace: %q / %q (%v, %v)", a, b, err1, err2)
		}
	}
	for _, want := range []string{providerCapacity, "turn.completed"} {
		if !strings.Contains(transcript.String(), want) {
			t.Errorf("transcript lost %q", want)
		}
	}
}

func TestCodexRetriesRateLimitsAndDroppedConnections(t *testing.T) {
	t.Parallel()
	cases := map[string]providerAttempt{
		"rate limit":           providerCodexFailure("Rate limit reached for requests; please try again later."),
		"connection":           providerCodexFailure("stream disconnected before completion: connection reset by peer"),
		"error without result": {out: providerJSON(map[string]string{"type": "error", "message": providerCapacity}), exit: 1},
		"stderr":               {stderr: "HTTP 429 Too Many Requests: rate limit exceeded\n", exit: 1},
	}
	for name, first := range cases {
		t.Run(name, func(t *testing.T) {
			t.Parallel()
			b, dir := providerBackend(t, "codex", first, providerSuccess("codex"))
			u, err := b.Run(providerContext(t), Job{Workspace: t.TempDir(), Prompt: "review", ReadOnly: true, Timeout: 30 * time.Second})
			if err != nil || u.Outcome != "success" || providerCount(t, dir) != 2 {
				t.Fatalf("temporary provider error was not retried successfully: %+v, %v, attempts=%d", u, err, providerCount(t, dir))
			}
		})
	}
}

func TestClaudeRetriesOverloadAndRateLimits(t *testing.T) {
	t.Parallel()
	cases := map[string]providerAttempt{
		"overloaded result":   providerClaudeFailure("API Error: 529 {\"error\":{\"type\":\"overloaded_error\",\"message\":\"Overloaded\"}}"),
		"rate-limited result": providerClaudeFailure("API Error: 429 {\"error\":{\"type\":\"rate_limit_error\",\"message\":\"Too many requests\"}}"),
		"error result text":   {out: "{\"type\":\"result\",\"subtype\":\"error_during_execution\",\"is_error\":true,\"result\":\"API Error: 529 overloaded_error\"}\n", exit: 1},
		"assistant API error": {out: "{\"type\":\"assistant\",\"error\":\"rate_limit\",\"message\":{\"content\":[{\"type\":\"text\",\"text\":\"API Error: 429 rate_limit_error\"}]}}\n{\"type\":\"result\",\"subtype\":\"error_during_execution\",\"is_error\":true}\n", exit: 1},
		"dropped connection":  {stderr: "API request failed: connection reset by peer\n", exit: 1},
	}
	for name, first := range cases {
		t.Run(name, func(t *testing.T) {
			t.Parallel()
			b, dir := providerBackend(t, "claude-code", first, providerSuccess("claude-code"))
			u, err := b.Run(providerContext(t), Job{Workspace: t.TempDir(), Prompt: "draft", GateServer: []string{"invariant", "mcp"}, Tools: []string{"check"}, Timeout: 30 * time.Second})
			if err != nil || u.Outcome != "success" || providerCount(t, dir) != 2 {
				t.Fatalf("temporary provider error was not retried successfully: %+v, %v, attempts=%d", u, err, providerCount(t, dir))
			}
		})
	}
}

func TestProviderRetriesAreBoundedAndKeepTheLastError(t *testing.T) {
	t.Parallel()
	for _, agent := range []string{"codex", "claude-code"} {
		t.Run(agent, func(t *testing.T) {
			t.Parallel()
			failure := providerCodexFailure
			message := providerCapacity
			if agent == "claude-code" {
				failure, message = providerClaudeFailure, "API Error: 529 overloaded_error"
			}
			last := message + " (last attempt)"
			b, dir := providerBackend(t, agent, failure(message+" (first attempt)"), failure(message+" (second attempt)"),
				failure(message+" (third attempt)"), failure(last), providerSuccess(agent))
			b = providerWithWait(b, providerScaledWait(600))
			start := time.Now()
			u, err := b.Run(providerContext(t), Job{Workspace: t.TempDir(), ReadOnly: true, Timeout: 35 * time.Second})
			providerUnavailable(t, err, last)
			if n := providerCount(t, dir); n != 4 || u.Outcome == "success" {
				t.Errorf("attempts=%d, usage=%+v; want failure after exactly four attempts", n, u)
			}
			if elapsed := time.Since(start); elapsed < 700*time.Millisecond || elapsed > 5*time.Second {
				t.Errorf("elapsed %s; want configured waits of 100, 200 and 400 milliseconds", elapsed)
			}
		})
	}
}

func TestProviderRetriesUseTheMinuteSchedule(t *testing.T) {
	// Observe the actual delays Run requests for both providers, without
	// sleeping for seven minutes or replacing the retrying code itself.
	for _, agent := range []string{"codex", "claude-code"} {
		t.Run(agent, func(t *testing.T) {
			failure, message := providerCodexFailure, providerCapacity
			if agent == "claude-code" {
				failure, message = providerClaudeFailure, "API Error: 529 overloaded_error"
			}
			last := message + " (fourth attempt)"
			for _, recovers := range []bool{false, true} {
				t.Run(fmt.Sprintf("fourth attempt succeeds=%v", recovers), func(t *testing.T) {
					fourth := failure(last)
					if recovers {
						fourth = providerSuccess(agent)
					}
					b, dir := providerBackend(t, agent, failure(message), failure(message), failure(message), fourth, providerSuccess(agent))
					var delays []time.Duration
					b = providerWithWait(b, func(ctx context.Context, delay time.Duration) error {
						delays = append(delays, delay)
						return ctx.Err()
					})
					u, err := b.Run(providerContext(t), Job{Workspace: t.TempDir(), ReadOnly: true, Timeout: 10 * time.Second})
					if recovers {
						if err != nil || u.Outcome != "success" {
							t.Errorf("recovery on fourth attempt: usage=%+v, error=%v", u, err)
						}
					} else {
						providerUnavailable(t, err, last)
						if u.Outcome == "success" {
							t.Error("four failed attempts reported success")
						}
					}
					if n := providerCount(t, dir); n != 4 {
						t.Errorf("attempts=%d; want exactly four", n)
					}
					want := []time.Duration{time.Minute, 2 * time.Minute, 4 * time.Minute}
					if !reflect.DeepEqual(delays, want) {
						t.Errorf("requested waits=%v; want %v with no wait before the first attempt or after the fourth", delays, want)
					}
				})
			}
		})
	}
}

func TestProviderRetriesStopAtOrdinaryFailures(t *testing.T) {
	t.Parallel()
	for _, agent := range []string{"codex", "claude-code"} {
		t.Run(agent, func(t *testing.T) {
			t.Parallel()
			failure, temporary := providerCodexFailure, providerCapacity
			if agent == "claude-code" {
				failure, temporary = providerClaudeFailure, "API Error: 529 overloaded_error"
			}
			ordinary := failure("Invalid API key: authentication failed")
			b, dir := providerBackend(t, agent, failure(temporary), ordinary, providerSuccess(agent))
			_, err := b.Run(providerContext(t), Job{Workspace: t.TempDir(), ReadOnly: true, Timeout: 30 * time.Second})
			if err == nil || providerCount(t, dir) != 2 || strings.Contains(strings.ToLower(err.Error()), "provider unavailable") {
				t.Errorf("capacity then authentication failure: attempts=%d, error=%v; want stop on the second attempt's ordinary failure", providerCount(t, dir), err)
			}
			// An ordinary failure on the first attempt is never retried either.
			// Words in normal agent output or failed tools are not provider errors.
			for _, message := range []string{"Invalid API key", "usage limit reached", "invalid model", "MCP servers failed to initialize"} {
				b, dir := providerBackend(t, agent, failure(message), providerSuccess(agent))
				_, err := b.Run(providerContext(t), Job{Workspace: t.TempDir(), ReadOnly: true})
				if err == nil || providerCount(t, dir) != 1 {
					t.Errorf("ordinary failure %q: attempts=%d, error=%v", message, providerCount(t, dir), err)
				}
			}
			// Startup errors carry connection language too. Preserve the full
			// diagnostic so this exercises its MCP context, including a failure
			// before any terminal agent event, rather than a bare connection
			// message that could legitimately describe the model provider.
			diagnostic := "mcp: invariant starting\n" +
				"mcp: invariant failed: MCP client for `invariant` failed to start: MCP startup failed: handshaking with MCP server failed: connection closed: initialize response\n" +
				"mcp startup: failed: invariant\n" +
				"Error: required MCP servers failed to initialize: invariant\n"
			cause := "connection closed: initialize response"
			if agent == "claude-code" {
				diagnostic = "MCP server \"invariant\": Connection failed: McpError: MCP error -32000: Connection closed\n" +
					"MCP server \"invariant\": Error message: MCP error -32000: Connection closed\n" +
					"Error: Failed to initialize MCP server \"invariant\"\n"
				cause = "MCP error -32000: Connection closed"
			}
			for _, afterTransient := range []bool{false, true} {
				t.Run(fmt.Sprintf("MCP startup after provider outage=%v", afterTransient), func(t *testing.T) {
					attempts := []providerAttempt{{stderr: diagnostic, exit: 1}, providerSuccess(agent)}
					wantAttempts, wantWaits := 1, 0
					if afterTransient {
						attempts = append([]providerAttempt{failure(temporary)}, attempts...)
						wantAttempts, wantWaits = 2, 1
					}
					b, dir := providerBackend(t, agent, attempts...)
					var waits []time.Duration
					b = providerWithWait(b, func(ctx context.Context, delay time.Duration) error {
						waits = append(waits, delay)
						return ctx.Err()
					})
					u, err := b.Run(providerContext(t), Job{Workspace: t.TempDir(),
						GateServer: []string{"invariant", "mcp"}, Tools: []string{"test"}, Timeout: 10 * time.Second})
					if n := providerCount(t, dir); n != wantAttempts || len(waits) != wantWaits {
						t.Errorf("MCP startup failure: attempts=%d, waits=%v; want %d attempts and %d waits", n, waits, wantAttempts, wantWaits)
					}
					if err == nil || u.Outcome == "success" {
						t.Fatalf("MCP startup failure was accepted: usage=%+v, error=%v", u, err)
					}
					if !strings.Contains(err.Error(), cause) {
						t.Errorf("MCP startup error lost its cause %q: %v", cause, err)
					}
					message := strings.ToLower(err.Error())
					if strings.Contains(message, "provider") && strings.Contains(message, "unavailable") {
						t.Errorf("ordinary MCP startup failure was reported as provider unavailability: %v", err)
					}
				})
			}
			success := providerSuccess(agent)
			if agent == "codex" {
				success.out = "{\"type\":\"error\",\"message\":\"Reconnecting... 1/5\"}\n" +
					"{\"type\":\"item.completed\",\"item\":{\"type\":\"command_execution\",\"aggregated_output\":\"API Error: 429 rate limit exceeded\",\"exit_code\":1,\"status\":\"failed\"}}\n" + success.out
			} else {
				success.out = "{\"type\":\"assistant\",\"message\":{\"content\":[{\"type\":\"text\",\"text\":\"I fixed the overloaded_error and rate_limit_error handling.\"}]}}\n" + success.out
			}
			b, dir = providerBackend(t, agent, success)
			if _, err := b.Run(providerContext(t), Job{Workspace: t.TempDir(), ReadOnly: true}); err != nil || providerCount(t, dir) != 1 {
				t.Errorf("successful run was retried or rejected: attempts=%d, error=%v", providerCount(t, dir), err)
			}
		})
	}
}

func TestProviderWaitCountsAgainstTheRunTimeout(t *testing.T) {
	t.Parallel()
	for _, agent := range []string{"codex", "claude-code"} {
		t.Run(agent, func(t *testing.T) {
			t.Parallel()
			first, last := providerCodexFailure(providerCapacity), providerCapacity
			if agent == "claude-code" {
				last = "API Error: 529 overloaded_error"
				first = providerClaudeFailure(last)
			}
			b, dir := providerBackend(t, agent, first, providerSuccess(agent))
			b = providerWithWait(b, nil) // exercise the production timer
			start := time.Now()
			_, err := b.Run(providerContext(t), Job{Workspace: t.TempDir(), ReadOnly: true, Timeout: 300 * time.Millisecond})
			providerUnavailable(t, err, last)
			if !errors.Is(err, context.DeadlineExceeded) || providerCount(t, dir) != 1 {
				t.Errorf("timeout during backoff: attempts=%d, error=%v; want deadline exceeded without another attempt", providerCount(t, dir), err)
			}
			if elapsed := time.Since(start); elapsed < 250*time.Millisecond || elapsed > 3*time.Second {
				t.Errorf("timeout returned after %s; want the original 300ms budget", elapsed)
			}
		})
	}
}

func TestProviderRetriesKeepTheOriginalDeadline(t *testing.T) {
	t.Parallel()
	b, dir := providerBackend(t, "codex", providerCodexFailure(providerCapacity),
		providerCodexFailure("Rate limit reached on second attempt"), providerSuccess("codex"))
	start := time.Now()
	_, err := b.Run(providerContext(t), Job{Workspace: t.TempDir(), ReadOnly: true, Timeout: 6 * time.Second})
	providerUnavailable(t, err, "Rate limit reached on second attempt")
	if !errors.Is(err, context.DeadlineExceeded) || providerCount(t, dir) != 2 {
		t.Errorf("retry reset the time limit: attempts=%d, error=%v", providerCount(t, dir), err)
	}
	if elapsed := time.Since(start); elapsed < 6*time.Second || elapsed > 9*time.Second {
		t.Errorf("elapsed %s; want the original six-second deadline", elapsed)
	}
}

type providerNotice struct {
	once sync.Once
	seen chan struct{}
}

func (w *providerNotice) Write(p []byte) (int, error) {
	if bytes.Contains(p, []byte("turn.failed")) {
		w.once.Do(func() { close(w.seen) })
	}
	return len(p), nil
}

type providerRunResult struct {
	usage Usage
	err   error
}

func providerAsync(ctx context.Context, b Backend, job Job) <-chan providerRunResult {
	done := make(chan providerRunResult, 1)
	go func() {
		u, err := b.Run(ctx, job)
		done <- providerRunResult{u, err}
		close(done)
	}()
	return done
}

func TestCodexReleasesBothTurnsDuringProviderWait(t *testing.T) {
	// No parallel peers in this package can take the process-wide Codex turn
	// during this assertion; the second backend below is the competing step.
	b, dir := providerBackend(t, "codex", providerCodexFailure(providerCapacity), providerSuccess("codex"))
	c := b.(Codex)
	notice := &providerNotice{seen: make(chan struct{})}
	ctx, cancel := context.WithTimeout(t.Context(), 20*time.Second)
	done := providerAsync(ctx, c, Job{Workspace: t.TempDir(), ReadOnly: true, Timeout: 15 * time.Second, Transcript: notice})
	defer func() { cancel(); <-done }()
	select {
	case <-notice.seen:
	case <-ctx.Done():
		t.Fatal("first attempt did not report capacity")
	}
	select {
	case result := <-done:
		t.Fatalf("run returned instead of waiting to retry: %v", result.err)
	case <-time.After(200 * time.Millisecond):
	}
	// A separate descriptor represents another process using the same home.
	f, err := os.OpenFile(filepath.Join(c.Home, "invariant.lock"), os.O_RDWR, 0)
	if err != nil {
		t.Fatal(err)
	}
	if err := syscall.Flock(int(f.Fd()), syscall.LOCK_EX|syscall.LOCK_NB); err != nil {
		f.Close()
		t.Fatalf("provider wait still holds the cross-process turn: %v", err)
	}
	f.Close()
	other, otherDir := providerBackend(t, "codex", providerSuccess("codex"))
	second := other.(Codex)
	second.Home = c.Home
	secondCtx, stop := context.WithTimeout(ctx, 2*time.Second)
	defer stop()
	if u, err := second.Run(secondCtx, Job{Workspace: t.TempDir(), ReadOnly: true, Timeout: time.Second}); err != nil || u.Outcome != "success" {
		t.Fatalf("another step could not take the Codex turn during backoff: %+v, %v", u, err)
	}
	if providerCount(t, dir) != 1 || providerCount(t, otherDir) != 1 {
		t.Fatal("the other step did not run between the first step's attempts")
	}
	result := <-done
	if result.err != nil || result.usage.Outcome != "success" || providerCount(t, dir) != 2 {
		t.Fatalf("first step did not resume successfully: %+v, attempts=%d", result, providerCount(t, dir))
	}
}

func TestCancellingAProviderWaitStopsRetries(t *testing.T) {
	b, dir := providerBackend(t, "codex", providerCodexFailure(providerCapacity), providerSuccess("codex"))
	b = providerWithWait(b, nil) // cancellation must interrupt the real minute wait
	notice := &providerNotice{seen: make(chan struct{})}
	ctx, cancel := context.WithTimeout(t.Context(), 20*time.Second)
	done := providerAsync(ctx, b, Job{Workspace: t.TempDir(), ReadOnly: true, Transcript: notice})
	defer func() { cancel(); <-done }()
	select {
	case <-notice.seen:
	case <-ctx.Done():
		t.Fatal("first attempt did not run")
	}
	select {
	case result := <-done:
		t.Fatalf("run returned instead of waiting to retry: %v", result.err)
	case <-time.After(200 * time.Millisecond):
	}
	cancel()
	select {
	case result := <-done:
		if !errors.Is(result.err, context.Canceled) || providerCount(t, dir) != 1 {
			t.Fatalf("cancellation did not stop backoff: %+v, attempts=%d", result, providerCount(t, dir))
		}
	case <-time.After(2 * time.Second):
		t.Fatal("cancellation waited for the retry delay")
	}
}

func TestCodexRetryTurnWaitKeepsTheDeadline(t *testing.T) {
	b, dir := providerBackend(t, "codex", providerCodexFailure(providerCapacity), providerSuccess("codex"))
	c := b.(Codex)
	notice := &providerNotice{seen: make(chan struct{})}
	ctx, cancel := context.WithTimeout(t.Context(), 20*time.Second)
	start := time.Now()
	done := providerAsync(ctx, c, Job{Workspace: t.TempDir(), ReadOnly: true, Timeout: 6 * time.Second, Transcript: notice})
	defer func() { cancel(); <-done }()
	select {
	case <-notice.seen:
	case <-ctx.Done():
		t.Fatal("first attempt did not run")
	}
	select {
	case result := <-done:
		t.Fatalf("run returned instead of waiting to retry: %v", result.err)
	case <-time.After(200 * time.Millisecond):
	}
	long := providerSuccess("codex")
	long.before = "while [ ! -f \"$here/release\" ]; do sleep 0.05; done\n"
	other, otherDir := providerBackend(t, "codex", long)
	second := other.(Codex)
	second.Home = c.Home
	otherDone := providerAsync(ctx, second, Job{Workspace: t.TempDir(), ReadOnly: true})
	defer func() { cancel(); <-otherDone }()
	for {
		if _, err := os.Stat(filepath.Join(otherDir, "count")); err == nil {
			break
		}
		select {
		case <-ctx.Done():
			t.Fatal("the competing step never took its turn")
		case <-time.After(10 * time.Millisecond):
		}
	}
	select {
	case result := <-done:
		providerUnavailable(t, result.err, providerCapacity)
		if !errors.Is(result.err, context.DeadlineExceeded) || providerCount(t, dir) != 1 {
			t.Errorf("waiting to reacquire the turn reset the deadline: %+v, attempts=%d", result, providerCount(t, dir))
		}
		if elapsed := time.Since(start); elapsed < 6*time.Second || elapsed > 9*time.Second {
			t.Errorf("elapsed %s; want the original six-second deadline", elapsed)
		}
	case <-time.After(9 * time.Second):
		t.Fatal("the retry's turn wait did not observe the original deadline")
	}
	if err := os.WriteFile(filepath.Join(otherDir, "release"), nil, 0o600); err != nil {
		t.Fatal(err)
	}
	if result := <-otherDone; result.err != nil || result.usage.Outcome != "success" {
		t.Errorf("one step's expired retry canceled the competing step: %+v", result)
	}
}
